// DTO with annotations — declarative, runs automatically under [ApiController]
public record CreateOrderRequest
{
    [Required, StringLength(64)]
    public string CustomerId { get; init; } = "";

    [Range(0.01, 1_000_000)]
    public decimal Amount { get; init; }

    [EmailAddress]
    public string? ReceiptEmail { get; init; }
}

[ApiController]
[Route("api/orders")]
public class OrdersController : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<OrderDto>> Create(
        [FromBody] CreateOrderRequest request,   // body source pinned
        [FromQuery] bool dryRun = false,         // query source pinned
        CancellationToken cancellationToken)     // framework-provided binder
    {
        // ModelState is already validated — invalid body => automatic 400 ProblemDetails

        if (!await _rules.IsCustomerIdUniqueAsync(request.CustomerId, cancellationToken))
            ModelState.AddModelError(nameof(request.CustomerId), "Unknown customer");

        if (!ModelState.IsValid)
            return ValidationProblem(ModelState);   // manual business-rule failures

        return CreatedAtAction(nameof(Get), new { id = order.Id }, order);
    }
}

// Custom binder for a value type the framework shouldn't guess about
public class CurrencyBinder : IModelBinder
{
    public Task BindModelAsync(ModelBindingContext ctx)
    {
        var value = ctx.ValueProvider.GetValue(ctx.ModelName).FirstValue;
        ctx.Result = Currency.TryParse(value, out var c)
            ? ModelBindingResult.Success(c)
            : ModelBindingResult.Fail();
        return Task.CompletedTask;
    }
}
